using Dapper;using MySqlConnector;
namespace Commerce.Operations.Api.Dashboard;
public sealed class DashboardRepository(IConfiguration configuration){public async Task<(long TotalProducts,long ActiveProducts,long TotalCustomers,long ActiveCustomers)> SummaryAsync(){await using var connection=new MySqlConnection(configuration.GetConnectionString("Operations")??throw new InvalidOperationException("Operations connection string is required."));var row=await connection.QuerySingleAsync("SELECT (SELECT COUNT(*) FROM products) TotalProducts,(SELECT COUNT(*) FROM products WHERE status='ACTIVE') ActiveProducts,(SELECT COUNT(*) FROM customers) TotalCustomers,(SELECT COUNT(*) FROM customers WHERE status='ACTIVE') ActiveCustomers");return((long)row.TotalProducts,(long)row.ActiveProducts,(long)row.TotalCustomers,(long)row.ActiveCustomers);}}
